#!/usr/bin/env python3
"""Clarifies exactly which software is published, experimental or engineering expertise."""
from pathlib import Path
import json,re
from html import escape
R=Path(__file__).resolve().parents[1];BASE='/multiverse-ai-website/'
file=R/'technology/index.html';s=file.read_text()
proof=json.loads((R/'assets/kmd/answer-proof.json').read_text())
q=escape(proof['question']); a=escape(proof['answer']);ex=escape(proof['source_excerpt'].splitlines()[1])
main=f'''<main id="main" class="sw-software-page">
<section class="sw-subhero container"><p class="sw-kicker">SOFTWARE & AI · WHAT EXISTS</p><h1>Real applications, research prototypes, and engineering work.</h1><p>Multiverse builds software to reduce manual work and evaluate more complex AI and automation methods. This page tells you exactly what has been published, what has been tested experimentally, and what is still engineering work.</p><div class="sw-sub-links"><a class="sw-button sw-primary" href="{BASE}#software-proof">Watch the real software</a><a class="sw-button sw-outline" href="{BASE}opportunities/">Commercial possibilities</a></div></section>
<section class="sw-subsection sw-sub-light" id="published"><div class="container sw-sub-grid"><div><p class="sw-kicker sw-ink-kicker">PUBLISHED APPLICATION</p><h2>Late Order Monitor for Wix Stores</h2><p><strong>The problem:</strong> paid orders may remain unfulfilled. Someone needs to find the oldest exceptions and follow up.</p><p><strong>The application:</strong> a read-only order dashboard with age filtering and CSV export. It does not modify customer orders.</p><div class="sw-sub-links"><a class="sw-button sw-dark" href="{BASE}#software-proof">Watch the actual app</a><a class="sw-textlink sw-ink-link" href="https://multiverse-salvatorquaro1-0a0e.wix-site-host.com/" rel="noopener noreferrer" target="_blank">Visit published Wix app ↗</a></div></div><a class="sw-subshot" href="{BASE}#software-proof"><img src="{BASE}assets/focus/wix-dashboard-poster.webp" width="1280" height="720" alt="Actual order dashboard for the Late Order Monitor app" loading="lazy"><span>Actual published app recording</span></a></div></section>
<section class="sw-subsection sw-sub-deep" id="document-research"><div class="container sw-sub-grid"><div><p class="sw-kicker">VERIFIED RESEARCH TEST · NOT A FINISHED PRODUCT</p><h2>KnowMoreDiRT: ask questions about existing files</h2><p><strong>The problem:</strong> useful information is scattered across many reports, notes and log files. Searching manually is time-consuming.</p><p><strong>The intended workflow:</strong> point KMD at an existing folder of readable text, ask a question in normal language, and receive a plain answer. Source context is held internally so the result can be investigated. This could reduce manual searching, but the benefit is not yet validated at business scale.</p><details class="sw-sub-test-details"><summary>See the limited fictional test</summary><p><strong>Test question:</strong> <em>{q}</em></p><p><strong>Test answer:</strong> {a} — a made-up person in a fictional document, not a Multiverse employee.</p><p><strong>Original fictional file:</strong> <q>{ex}</q>.</p></details><p>This proves one bounded, model-verified test on a fictional one-file corpus, not broad production reliability or a live new query on the website.</p><div class="sw-sub-links"><a class="sw-button sw-primary" href="{BASE}kmd/evidence/#answer-proof">Inspect original evidence</a><a class="sw-textlink" href="{BASE}kmd/">See how the system would be used ↗</a></div></div><a class="sw-subshot" href="{BASE}kmd/evidence/#answer-proof"><img src="{BASE}assets/kmd/kmd-evidence-walkthrough-poster.webp" width="1280" height="800" alt="Recorded KMD source-evidence explorer from a fictional test" loading="lazy"><span>Previously recorded test evidence</span></a></div></section>
<section class="sw-subsection sw-sub-light" id="agents"><div class="container"><p class="sw-kicker sw-ink-kicker">ENGINEERING AREAS · NOT PACKAGED PRODUCTS</p><h2>Other software and automation work</h2><p class="sw-sublead">These are areas of engineering development, not a claim that all capabilities are for sale as finished applications.</p><div class="sw-sub-cards"><article><h3>Workflow and application automation</h3><p>Connect existing applications, browsers, tools and APIs, perform defined actions, and verify whether they succeeded.</p></article><article><h3>Software and test automation</h3><p>Build repeatable checks, validation scripts and data-processing tools so manual steps become testable procedures.</p></article><article><h3>Private AI components</h3><p>Integrate local language models with documents and specialized software, with attention to source references and control.</p></article></div></div></section>
<section class="sw-subsection sw-sub-end"><div class="container sw-sub-grid"><div><p class="sw-kicker">BUSINESS CONVERSATION</p><h2>Have a defined task worth automating?</h2><p>Discuss acquiring an existing software component, a specific adaptation, or another bounded technology opportunity. We can establish scope and readiness before making commitments.</p></div><div class="sw-sub-actions"><a class="sw-button sw-primary" href="{BASE}contact/">Discuss the problem</a><a class="sw-textlink" href="{BASE}3d/">Looking for 3D models instead? ↗</a></div></div></section>
</main>'''
match=re.search(r'<main\b[^>]*\bid="main"[^>]*>',s)
assert match, "no main#main found"
start=match.start();end=s.index('</main>',start)+len('</main>')
s=s[:start]+main+s[end:]
s=re.sub(r'<title>.*?</title>','<title>Software & AI Projects | Multiverse</title>',s,count=1)
s=re.sub(r'<meta content="[^"]*" name="description"/>','<meta content="Published Wix order-monitoring software, source-backed document AI research, and workflow and testing automation expertise." name="description"/>',s,count=1)
if '/multiverse-ai-website/assets/software-first.css' not in s:s=s.replace('</head>','<link href="/multiverse-ai-website/assets/software-first.css" rel="stylesheet"/></head>',1)
file.write_text(s)
from render_software_portfolio import replace_technology
replace_technology()
print('WROTE',file)
